// CBSE 12 Mathematics ch12 Linear Programming — practice bank with independent re-solve checks:
// every corner is recomputed by intersecting boundary lines and filtering by all constraints (lp.mjs),
// every optimum by evaluating Z at the corners AND by a brute-force grid search of the region, and every
// unbounded case by the open half-plane test on a large grid. The deleted classification of LPP types
// (manufacturing, diet, transportation) is not taught or asked anywhere.
import { Q, caseQ, child, mk, r } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { solveLP, corners, feasible, sameSet } from './lp.mjs';

/** Regions used by the bank (x ≥ 0, y ≥ 0 always added). */
export const REG = {
  R1: [[1, 1, '<=', 8], [1, 2, '<=', 10]],
  R2: [[1, 1, '>=', 6], [1, 3, '>=', 9]],
  BAKE: [[2, 1, '<=', 40], [2, 3, '<=', 72]],
  A: [[3, 2, '<=', 18], [1, 2, '<=', 10]],
  B: [[1, 1, '<=', 7], [2, 1, '<=', 10]],
  C: [[2, 1, '>=', 8], [1, 2, '>=', 7]],
  D: [[1, 2, '>=', 4], [1, 1, '<=', 6]],
  D5: [[1, 2, '>=', 4], [1, 1, '<=', 6], [1, 0, '<=', 5]],
  E: [[1, 1, '<=', 10], [1, 0, '<=', 6], [0, 1, '<=', 8]],
  F: [[1, 3, '<=', 15], [2, 1, '<=', 10]],
  G: [[1, 1, '<=', 3], [2, 3, '>=', 12]],
  H: [[3, 1, '>=', 9], [1, 1, '>=', 5], [1, 3, '>=', 9]],
  J: [[5, 4, '<=', 40], [1, 2, '<=', 14]],
  K: [[1, 1, '>=', 2], [1, 0, '<=', 4], [0, 1, '<=', 3]],
};
const S = (reg, p, q, kind) => solveLP(Array.isArray(reg) ? reg : REG[reg], p, q, kind);
const has = (pts, x, y) => pts.some(([u, v]) => Math.abs(u - x) < 1e-9 && Math.abs(v - y) < 1e-9);

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: 'In a linear programming problem, the objective function is', opts: ['a linear function of the decision variables that is to be maximised or minimised', 'any one of the constraints written as an equation', 'the set of all points satisfying the constraints', 'a quadratic expression in the decision variables'], key: 'a', sol: 'The objective function $Z = ax + by$ is the linear quantity (profit, cost, time) we optimise. Option (c) describes the feasible region, not the objective.', d: 1, c: 'recall', t: [1], time: 30 }), (C) => C.key('a'));
Q('m02', mk.mcq({ stem: r`Why are the conditions $x \ge 0$, $y \ge 0$ included in almost every linear programming problem drawn from real life?`, opts: ['Quantities such as numbers of items, hours or kilograms cannot be negative', 'They make the objective function linear', 'They guarantee that the feasible region is bounded', 'They make the optimal solution unique'], key: 'a', sol: 'These are the non-negativity constraints: decision variables count or measure real things. They do not by themselves make the region bounded or the optimum unique.', d: 1, c: 'recall', t: [1], time: 40 }), (C) => { C.assert(!S([[1, 1, '>=', 1]], 1, 1, 'max').bounded, 'non-negativity alone does not bound a region'); C.key('a'); });
Q('m03', mk.mcq({ stem: r`Which of these points satisfies the inequality $2x + 3y \le 12$?`, opts: ['$(3, 2)$', '$(4, 2)$', '$(5, 1)$', '$(1, 4)$'], key: 'a', sol: r`Substitute: $(3, 2)$ gives $6 + 6 = 12$, which is allowed because the inequality includes equality. The others give $14$, $13$ and $14$.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => C.which([[3, 2], [4, 2], [5, 1], [1, 4]].map(([x, y]) => 2 * x + 3 * y <= 12), true));
Q('m04', mk.mcq({ stem: r`The feasible region of $x + y \le 8$, $x + 2y \le 10$, $x \ge 0$, $y \ge 0$ is a quadrilateral. Which of the following is **not** one of its corner points?`, opts: ['$(8, 0)$', '$(6, 2)$', '$(0, 5)$', '$(0, 8)$'], key: 'd', sol: r`$(0, 8)$ lies on $x + y = 8$ but gives $0 + 16 = 16 > 10$, so it breaks the second constraint. The corners are $(0, 0)$, $(8, 0)$, $(6, 2)$ and $(0, 5)$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const cs = corners(REG.R1); C.which([[8, 0], [6, 2], [0, 5], [0, 8]].map(([x, y]) => !has(cs, x, y)), true); });
Q('m05', mk.mcq({ stem: r`A bounded feasible region has corner points $(0, 0)$, $(6, 0)$, $(4, 3)$ and $(0, 5)$. The maximum value of $Z = 3x + 4y$ on it is`, opts: ['$24$', '$20$', '$18$', '$25$'], key: 'a', sol: r`Corner values: $0$, $18$, $24$, $20$. The largest is $24$ at $(4, 3)$. Option (b) is the value at $(0, 5)$ only.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const s = S('A', 3, 4, 'max'); C.assert(sameSet(s.corners, [[0, 0], [6, 0], [4, 3], [0, 5]]), 'corners'); C.which([24, 20, 18, 25], s.value); });
Q('m06', mk.mcq({ stem: r`For the constraints $x + y \ge 4$, $x \ge 0$, $y \ge 0$, the feasible region is`, opts: ['unbounded', 'a triangle', 'empty', 'a single point'], key: 'a', sol: r`Every point beyond the line $x + y = 4$ in the first quadrant is feasible, for example $(100, 100)$, so the region stretches without end: it is unbounded.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { const s = S([[1, 1, '>=', 4]], 1, 1, 'min'); C.which(['unbounded', 'triangle', 'empty', 'point'], s.bounded ? 'triangle' : 'unbounded'); C.assert(feasible([[1, 1, '>=', 4]], 100, 100), '(100, 100) feasible'); });
Q('m07', mk.mcq({ stem: r`The unbounded region defined by $2x + y \ge 8$, $x + 2y \ge 7$, $x, y \ge 0$ has corners $(0, 8)$, $(3, 2)$ and $(7, 0)$. For $Z = 6x + 4y$, the least value on this region is`, opts: ['$26$', '$32$', '$42$', 'not attained, as the region is unbounded'], key: 'a', sol: r`Corner values: $32$, $26$, $42$. The smallest is $26$; because the region is unbounded, check that $6x + 4y < 26$ has no point in common with it — it has none, so the minimum is $26$ at $(3, 2)$.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => { const s = S('C', 6, 4, 'min'); C.assert(s.exists && !s.bounded, 'min exists on unbounded'); C.which([26, 32, 42, 'none'], s.value); });
Q('m08', mk.mcq({ stem: 'If the feasible region of a linear programming problem is bounded and non-empty, then the objective function', opts: ['has both a maximum and a minimum, each at a corner point', 'has a maximum but may have no minimum', 'has its optimum only at an interior point', 'may have neither a maximum nor a minimum'], key: 'a', sol: 'Corner Point Theorem: on a bounded (and non-empty) feasible region, $Z = ax + by$ attains both a maximum and a minimum, and each occurs at a corner point.', d: 1, c: 'recall', t: [2], time: 40 }), (C) => { const a = S('A', 2, 7, 'max'), b = S('A', 2, 7, 'min'); C.assert(a.exists && b.exists && a.bounded, 'bounded region has both'); C.key('a'); });
Q('m09', mk.mcq({ stem: 'An objective function takes the same maximum value at two adjacent corner points of a bounded feasible region. Then the maximum occurs', opts: ['at every point of the edge joining those two corners', 'only at those two corner points', 'at no point, since the optimum must be unique', 'only at the midpoint of the edge joining them'], key: 'a', sol: r`$Z$ is linear, so along the edge it changes uniformly; equal values at both ends mean it is constant on the whole edge. There are infinitely many optimal solutions.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { const s = S('F', 4, 2, 'max'); C.assert(s.at.length === 2 && 4 * 4 + 2 * 2 === s.value, 'midpoint (4, 2) of the edge also optimal'); C.key('a'); });
Q('m10', mk.mcq({ stem: r`How many corner points does the feasible region of $x + y \ge 2$, $x \le 4$, $y \le 3$, $x \ge 0$, $y \ge 0$ have?`, opts: ['$5$', '$4$', '$3$', '$6$'], key: 'a', sol: r`The corners are $(2, 0)$, $(4, 0)$, $(4, 3)$, $(0, 3)$ and $(0, 2)$: a pentagon, so $5$ corners. The origin is cut away by $x + y \ge 2$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which([5, 4, 3, 6], corners(REG.K).length));
Q('m11', mk.mcq({ stem: r`The boundary lines $2x + y = 10$ and $x + y = 7$ meet at a corner of a feasible region. That corner is`, opts: ['$(3, 4)$', '$(4, 3)$', '$(5, 0)$', '$(0, 7)$'], key: 'a', sol: r`Subtract: $x = 3$; then $y = 7 - 3 = 4$. Check: $6 + 4 = 10$. Option (b) swaps the coordinates.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { const x = 10 - 7, y = 7 - x; C.which([[3, 4], [4, 3], [5, 0], [0, 7]], [x, y]); C.assert(2 * x + y === 10, 'on both lines'); });
Q('m12', mk.mcq({ stem: r`A baker in Kanpur uses $300$ g of flour for each sponge cake and $150$ g for each fruit cake, and has $6$ kg of flour for the day. With $x$ sponge cakes and $y$ fruit cakes, the flour constraint is`, opts: [r`$2x + y \le 40$`, r`$x + 2y \le 40$`, r`$2x + y \ge 40$`, r`$300x + 150y \le 6$`], key: 'a', sol: r`Flour used: $300x + 150y \le 6000$ (grams). Dividing by $150$: $2x + y \le 40$. Option (d) mixes grams with kilograms.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => { const ok = (x, y) => 300 * x + 150 * y <= 6000; C.assert([[20, 0], [10, 20], [0, 40], [15, 9]].every(([x, y]) => ok(x, y) === (2 * x + y <= 40)) && ok(20, 0) && !ok(21, 0), 'equivalent'); C.key('a'); });
Q('m13', mk.mcq({ stem: r`Consider the constraints $x + y \le 3$, $2x + 3y \ge 12$, $x \ge 0$, $y \ge 0$. Which statement is correct?`, opts: ['There is no feasible region, so the problem has no solution', 'The feasible region is unbounded', 'The only feasible point is $(0, 3)$', 'The feasible region is a triangle'], key: 'a', sol: r`On $x + y \le 3$ in the first quadrant, $2x + 3y$ is at most $9$ (at $(0, 3)$), which is less than $12$. No point satisfies both, so the region is empty. At $(0, 3)$, $2x + 3y$ is only $9$.`, d: 3, c: 'analysis', t: [2], time: 75 }), (C) => { const s = S('G', 1, 1, 'max'); C.assert(s.empty, 'empty region'); C.assert(S([[1, 1, '<=', 3]], 2, 3, 'max').value === 9, 'max 2x + 3y = 9'); C.key('a'); });
Q('m14', mk.mcq({ stem: r`On the region with corners $(0, 0)$, $(5, 0)$, $(3, 4)$, $(0, 5)$, the function $Z = 4x + 2y$ is maximised. The number of optimal solutions is`, opts: ['infinitely many', 'exactly one', 'exactly two', 'none'], key: 'a', sol: r`$Z(5, 0) = 20$ and $Z(3, 4) = 20$ are equal and largest, so every point of the edge joining them is optimal: infinitely many solutions.`, d: 3, c: 'application', t: [2], time: 60 }), (C) => { const s = S('F', 4, 2, 'max'); C.assert(sameSet(s.corners, [[0, 0], [5, 0], [3, 4], [0, 5]]), 'corners'); C.which(['inf', 'one', 'two', 'none'], s.at.length >= 2 ? 'inf' : 'one'); });
Q('m15', mk.mcq({ stem: r`A feasible region is unbounded with corners $(0, 8)$, $(3, 2)$, $(7, 0)$ and comes from $2x + y \ge 8$, $x + 2y \ge 7$, $x, y \ge 0$. The minimum of $Z = 3x + 5y$ is`, opts: ['$19$', '$21$', '$40$', 'not attained'], key: 'a', sol: r`Corner values: $40$, $19$, $21$. Smallest: $19$. The open half-plane $3x + 5y < 19$ has no point of the region, so the minimum is $19$ at $(3, 2)$.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => { const s = S('C', 3, 5, 'min'); C.assert(s.exists, 'attained'); C.which([19, 21, 40, 'none'], s.value); });
Q('m16', mk.mcq({ stem: r`A shop's feasible region is given by $x + y \le 10$, $x \le 6$, $y \le 8$, $x, y \ge 0$. The greatest value of $Z = 5x + 7y$ is`, opts: ['$66$', '$58$', '$56$', '$70$'], key: 'a', sol: r`Corners: $(0, 0)$, $(6, 0)$, $(6, 4)$, $(2, 8)$, $(0, 8)$ with values $0$, $30$, $58$, $66$, $56$. The greatest is $66$ at $(2, 8)$. Option (d) uses $(0, 10)$, which breaks $y \le 8$.`, d: 3, c: 'application', t: [2], time: 90 }), (C) => C.which([66, 58, 56, 70], S('E', 5, 7, 'max').value));
Q('m17', mk.mcq({ stem: 'Because of the non-negativity constraints, the feasible region of a two-variable linear programming problem always lies in', opts: ['the first quadrant (including the axes)', 'the second quadrant', 'the half-plane above the x-axis only', 'the region between the two axes and the origin only'], key: 'a', sol: r`$x \ge 0$ keeps points to the right of (or on) the y-axis and $y \ge 0$ keeps them above (or on) the x-axis: together, the first quadrant with its boundary.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => { C.assert(!feasible([], -1, 2) && !feasible([], 1, -2) && feasible([], 0, 0), 'first quadrant'); C.key('a'); });
Q('m18', mk.mcq({ stem: r`To shade the region $x + 2y \ge 6$, a student tests the origin. What should she conclude?`, opts: ['$0 \\ge 6$ is false, so shade the side of the line away from the origin', '$0 \\ge 6$ is false, so shade the side containing the origin', 'The origin lies on the line, so another test point is needed', 'The test is true, so shade the side containing the origin'], key: 'a', sol: r`At $(0, 0)$: $0 + 0 \ge 6$ is false. The origin is not in the region, so the region is the side of $x + 2y = 6$ away from the origin.`, d: 1, c: 'understanding', t: [2], time: 45 }), (C) => { C.assert(!feasible([[1, 2, '>=', 6]], 0, 0) && feasible([[1, 2, '>=', 6]], 6, 6), 'origin outside'); C.key('a'); });

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`The maximum value of $Z = x + y$ subject to $x + y \le 5$, $x \ge 0$, $y \ge 0$ is $5$.`, r: 'On a bounded feasible region, the maximum of a linear objective function occurs at a corner point.', key: 'a', sol: r`Corners $(0, 0)$, $(5, 0)$, $(0, 5)$ give $0$, $5$, $5$, so the maximum is $5$. R is the Corner Point Theorem, which is exactly why checking the corners settles A.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(S([[1, 1, '<=', 5]], 1, 1, 'max').value === 5, 'max 5'); C.key('a'); });
Q('ar2', mk.ar({ a: r`The feasible region of $x + y \ge 3$, $x \ge 0$, $y \ge 0$ is unbounded.`, r: r`Every feasible region defined by "$\ge$" constraints is unbounded.`, key: 'c', sol: r`A is true: points such as $(50, 50)$ are feasible. R is false: $x + 2y \ge 4$ together with $x + y \le 6$ has corners $(4, 0)$, $(6, 0)$, $(0, 6)$, $(0, 2)$ — a bounded region with a "$\ge$" constraint.`, d: 2, c: 'analysis', t: [2] }), (C) => { C.assert(!S([[1, 1, '>=', 3]], 1, 1, 'min').bounded && S('D', 1, 1, 'max').bounded && sameSet(corners(REG.D), [[4, 0], [6, 0], [0, 6], [0, 2]]), 'A true, R false'); C.key('c'); });
Q('ar3', mk.ar({ a: r`The origin is a feasible point for the constraint $2x + 3y \ge 6$.`, r: 'A point is feasible only if it satisfies every constraint of the problem.', key: 'd', sol: r`At $(0, 0)$, $2x + 3y = 0$, which is not at least $6$, so A is false. R is the correct definition of a feasible point.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(!feasible([[2, 3, '>=', 6]], 0, 0), 'origin infeasible'); C.key('d'); });
Q('ar4', mk.ar({ a: r`On the region $x + y \ge 2$, $x \le 4$, $y \le 3$, $x, y \ge 0$, the maximum of $Z = x + 3y$ is attained at $(4, 3)$.`, r: r`$(4, 3)$ is a corner point of this region.`, key: 'b', sol: r`Corner values of $Z$: $(2, 0) \to 2$, $(4, 0) \to 4$, $(4, 3) \to 13$, $(0, 3) \to 9$, $(0, 2) \to 6$; the maximum $13$ is at $(4, 3)$, so A is true. R is true too, but being a corner does not make a point optimal — $(0, 2)$ is also a corner. R does not explain A.`, d: 3, c: 'analysis', t: [2] }), (C) => { const s = S('K', 1, 3, 'max'); C.assert(s.value === 13 && sameSet(s.at, [[4, 3]]) && has(s.corners, 0, 2), 'A and R true'); C.key('b'); });
Q('ar5', mk.ar({ a: r`On the region $2x + y \ge 8$, $x + 2y \ge 7$, $x, y \ge 0$, the minimum value $7$ of $Z = x + 2y$ is attained at infinitely many points.`, r: 'When an objective function takes the same optimal value at two adjacent corner points, it takes that value at every point of the edge joining them.', key: 'a', sol: r`$Z(3, 2) = 7$ and $Z(7, 0) = 7$, while $Z(0, 8) = 16$; and $x + 2y < 7$ contains no feasible point (it contradicts a constraint). So the minimum $7$ holds on the whole edge from $(3, 2)$ to $(7, 0)$, which is what R explains.`, d: 3, c: 'analysis', t: [2] }), (C) => { const s = S('C', 1, 2, 'min'); C.assert(s.exists && s.value === 7 && s.at.length === 2, 'two optimal corners'); C.key('a'); });
Q('ar6', mk.ar({ a: r`For $x + y \le 7$, $2x + y \le 10$, $x, y \ge 0$, the maximum of $Z = 2x + 5y$ occurs at $(3, 4)$.`, r: r`$(3, 4)$ is the point where the two lines $x + y = 7$ and $2x + y = 10$ meet.`, key: 'd', sol: r`Corner values: $(0, 0) \to 0$, $(5, 0) \to 10$, $(3, 4) \to 26$, $(0, 7) \to 35$. The maximum $35$ is at $(0, 7)$, so A is false. R is true: $3 + 4 = 7$ and $6 + 4 = 10$.`, d: 2, c: 'application', t: [2] }), (C) => { const s = S('B', 2, 5, 'max'); C.assert(s.value === 35 && sameSet(s.at, [[0, 7]]) && 3 + 4 === 7 && 6 + 4 === 10, 'A false, R true'); C.key('d'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: 'Every point of the feasible region is an optimal solution of the linear programming problem.', key: 'f', sol: r`False. Every point of the feasible region is a **feasible** solution; an **optimal** solution is a feasible point where $Z$ is largest (or smallest).`, d: 1, c: 'recall', t: [1] }), (C) => { const s = S('R1', 3, 5, 'max'); C.assert(s.values.some((v) => v !== s.value), 'some feasible corner not optimal'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`The point $(2, 2)$ lies in the feasible region of $x + 2y \le 8$, $3x + y \le 9$, $x \ge 0$, $y \ge 0$.`, key: 't', sol: r`True: $2 + 4 = 6 \le 8$ and $6 + 2 = 8 \le 9$, and both coordinates are non-negative.`, d: 1, c: 'understanding', t: [2] }), (C) => { C.assert(feasible([[1, 2, '<=', 8], [3, 1, '<=', 9]], 2, 2), 'feasible'); C.key('t'); });
Q('tf3', mk.tf({ stem: 'If a feasible region is unbounded, the objective function can still have a minimum value on it.', key: 't', sol: r`True. For example, on $x + y \ge 6$, $x + 3y \ge 9$, $x, y \ge 0$, $Z = 2x + 3y$ has minimum $13.5$ at $(4.5, 1.5)$ even though the region is unbounded; the half-plane test confirms it.`, d: 2, c: 'understanding', t: [2] }), (C) => { const s = S('R2', 2, 3, 'min'); C.assert(!s.bounded && s.exists && s.value === 13.5, 'min 13.5 on unbounded'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`On the region $x + y \le 8$, $x + 2y \le 10$, $x, y \ge 0$, the function $Z = 2x + 3y$ is greatest at the corner $(8, 0)$.`, key: 'f', sol: r`False. $Z(8, 0) = 16$ but $Z(6, 2) = 18$, which is the greatest of the corner values $0$, $16$, $18$, $15$.`, d: 2, c: 'application', t: [2] }), (C) => { const s = S('R1', 2, 3, 'max'); C.assert(s.value === 18 && !has(s.at, 8, 0), 'max at (6, 2)'); C.key('f'); });
Q('tf5', mk.tf({ stem: 'In a linear programming problem, a constraint such as $xy \\le 20$ is allowed.', key: 'f', sol: r`False. All constraints and the objective must be **linear** in the decision variables; $xy$ is a product of the variables, so it is not linear.`, d: 1, c: 'recall', t: [1] }), (C) => C.key('f'));

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: 'The common region determined by all the constraints, including the non-negativity constraints, is called the ____ region.', acc: [['feasible']], sol: 'It is the feasible region; points outside it are infeasible.', d: 1, c: 'recall', t: [1] }), (C) => C.blank('feasible'));
Q('fb2', mk.fill({ stem: r`The lines $x + y = 7$ and $2x + y = 10$ cross at a corner whose $x$-coordinate is ____.`, acc: [['3']], sol: r`Subtracting the first from the second gives $x = 3$ (and then $y = 4$).`, d: 1, c: 'understanding', t: [2] }), (C) => C.blank(10 - 7));
Q('fb3', mk.fill({ stem: r`The corners of a feasible region are $(0, 0)$, $(5, 0)$, $(3, 4)$ and $(0, 7)$. The maximum value of $Z = 2x + y$ on it is ____.`, acc: [['10']], sol: r`Corner values $0$, $10$, $10$, $7$; the maximum is $10$ (reached at two corners).`, d: 2, c: 'understanding', t: [2] }), (C) => { const s = S('B', 2, 1, 'max'); C.assert(sameSet(s.corners, [[0, 0], [5, 0], [3, 4], [0, 7]]), 'corners'); C.blank(s.value); });
Q('fb4', mk.fill({ stem: 'The linear function $Z = ax + by$ whose value is to be made as large or as small as possible is called the ____ function.', acc: [['objective']], sol: 'It is the objective function of the problem.', d: 1, c: 'recall', t: [1] }), (C) => C.blank('objective'));
Q('fb5', mk.fill({ stem: r`The feasible region of $x + y \le 10$, $x \le 6$, $y \le 8$, $x \ge 0$, $y \ge 0$ has ____ corner points.`, acc: [['5']], sol: r`Corners $(0, 0)$, $(6, 0)$, $(6, 4)$, $(2, 8)$, $(0, 8)$, so $5$ corners.`, d: 2, c: 'understanding', t: [2] }), (C) => C.blank(corners(REG.E).length));

// =============================================================== numerical
Q('n1', mk.num({ stem: r`Find the minimum value of $Z = 3x + 5y$ over the region bounded by $x + 2y \ge 4$, $x + y \le 6$, $x \ge 0$, $y \ge 0$.`, value: 10, sol: r`Corners $(4, 0)$, $(6, 0)$, $(0, 6)$, $(0, 2)$ give $12$, $18$, $30$, $10$. Minimum $10$ at $(0, 2)$.`, scheme: [['10', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => C.val(S('D', 3, 5, 'min').value));
Q('n2', mk.num({ stem: r`A potter in Khurja makes $x$ mugs and $y$ bowls a day with $5x + 4y \le 40$ (kiln slots) and $x + 2y \le 14$ (glazing hours). Profit is ₹$40$ per mug and ₹$50$ per bowl. What is the greatest daily profit in rupees?`, value: 410, unit: '₹', sol: r`Corners $(0, 0)$, $(8, 0)$, $(4, 5)$, $(0, 7)$ give ₹$0$, ₹$320$, ₹$410$, ₹$350$. Greatest: ₹$410$ with $4$ mugs and $5$ bowls.`, scheme: [['410', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => C.val(S('J', 40, 50, 'max').value));
Q('n3', mk.num({ stem: r`Two boundary lines of a feasible region are $3x + y = 9$ and $x + y = 5$. Find the $y$-coordinate of the corner where they meet.`, value: 3, sol: r`Subtract: $2x = 4$, so $x = 2$ and $y = 3$.`, scheme: [['3', 1]], d: 1, c: 'understanding', t: [2], time: 60 }), (C) => { const x = (9 - 5) / 2; C.val(5 - x); });
Q('n4', mk.num({ stem: r`The constraints $3x + y \ge 9$, $x + y \ge 5$, $x + 3y \ge 9$, $x, y \ge 0$ give an unbounded region. Find the minimum value of $Z = 2x + y$ on it.`, value: 7, sol: r`Corners $(0, 9)$, $(2, 3)$, $(3, 2)$, $(9, 0)$ give $9$, $7$, $8$, $18$. The half-plane $2x + y < 7$ has no feasible point, so the minimum is $7$.`, scheme: [['7', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const s = S('H', 2, 1, 'min'); C.assert(s.exists && !s.bounded, 'attained'); C.val(s.value); });
Q('n5', mk.num({ stem: r`Maximise $Z = 10x + 6y$ given $x + y \le 7$, $2x + y \le 10$, $x \ge 0$, $y \ge 0$, and enter the maximum value.`, value: 54, sol: r`Corners $(0, 0)$, $(5, 0)$, $(3, 4)$, $(0, 7)$ give $0$, $50$, $54$, $42$. Maximum $54$ at $(3, 4)$.`, scheme: [['54', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => C.val(S('B', 10, 6, 'max').value));
Q('n6', mk.num({ stem: r`Three "at least" constraints $3x + y \ge 9$, $x + y \ge 5$, $x + 3y \ge 9$, together with $x \ge 0$ and $y \ge 0$, cut out an open-ended region. Count its vertices and enter that number.`, value: 4, sol: r`They are $(0, 9)$, $(2, 3)$, $(3, 2)$ and $(9, 0)$: $4$ corners on an unbounded region.`, scheme: [['4', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => C.val(corners(REG.H).length));
Q('n7', mk.num({ stem: r`On the pentagon-shaped region $x + y \ge 2$, $x \le 4$, $y \le 3$, $x, y \ge 0$, what is the smallest value that $Z = 7x + 3y$ can take?`, value: 6, sol: r`Corner values: $(2, 0) \to 14$, $(4, 0) \to 28$, $(4, 3) \to 37$, $(0, 3) \to 9$, $(0, 2) \to 6$. Smallest: $6$.`, scheme: [['6', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => C.val(S('K', 7, 3, 'min').value));

// =============================================================== short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`For the constraints $3x + 2y \le 18$, $x + 2y \le 10$, $x, y \ge 0$, decide whether each of the points $P(2, 3)$ and $Q(5, 2)$ is feasible. Give reasons.`, model: r`$P(2, 3)$: $6 + 6 = 12 \le 18$ and $2 + 6 = 8 \le 10$, coordinates non-negative, so $P$ is **feasible**.

$Q(5, 2)$: $15 + 4 = 19 > 18$, so the first constraint fails and $Q$ is **not feasible**.`, sol: 'Substitute each point into every constraint.', scheme: [['P checked in both constraints: feasible', 1], ['Q fails 3x + 2y ≤ 18: infeasible', 1]], d: 1, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(feasible(REG.A, 2, 3) && !feasible(REG.A, 5, 2), 'P in, Q out'); C.model([12, 8, 19]); });
Q('s202', mk.short({ marks: 2, stem: r`The lines $x + 2y = 10$ and $3x + 2y = 18$ bound a feasible region. Find the corner where they meet and verify it.`, model: r`Subtract the first equation from the second: $2x = 8$, so $x = 4$. Then $2y = 10 - 4 = 6$, so $y = 3$.

Corner: $(4, 3)$. Check: $4 + 6 = 10$ and $12 + 6 = 18$.`, sol: 'Eliminate y by subtraction.', scheme: [['x = 4', 1], ['y = 3 with check', 1]], d: 1, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(has(corners(REG.A), 4, 3), 'corner'); C.model([4, 3, 10, 18]); });
Q('s203', mk.short({ marks: 2, stem: r`The corner points of a bounded feasible region are $(0, 0)$, $(5, 0)$, $(3, 4)$ and $(0, 5)$. Find the maximum and minimum values of $Z = 2x + 5y$.`, model: r`$Z(0, 0) = 0$, $Z(5, 0) = 10$, $Z(3, 4) = 6 + 20 = 26$, $Z(0, 5) = 25$.

Maximum $26$ at $(3, 4)$; minimum $0$ at $(0, 0)$.`, sol: 'Evaluate Z at each corner; the region is bounded.', scheme: [['All four corner values', 1], ['Max 26 at (3, 4), min 0 at (0, 0)', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { const a = S('F', 2, 5, 'max'), b = S('F', 2, 5, 'min'); C.assert(sameSet(a.corners, [[0, 0], [5, 0], [3, 4], [0, 5]]), 'corners'); C.model([a.value, b.value, 25, 10]); });
Q('s204', mk.short({ marks: 2, stem: r`An electronics shop in Patna stocks pressure cookers ($x$) and mixers ($y$). A cooker costs the shop ₹$1200$ and a mixer ₹$1800$; it can invest at most ₹$36000$ and has shelf room for at most $25$ boxes. Write the constraints of the problem in simplest form.`, model: r`Money: $1200x + 1800y \le 36000$, which divides by $600$ to give $2x + 3y \le 60$.

Shelf room: $x + y \le 25$.

Non-negativity: $x \ge 0$, $y \ge 0$.`, sol: 'One constraint per limited resource, then non-negativity.', scheme: [['2x + 3y ≤ 60', 1], ['x + y ≤ 25 and x, y ≥ 0', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { const ok = [[30, 0], [0, 20], [15, 10], [10, 14]].every(([x, y]) => (1200 * x + 1800 * y <= 36000) === (2 * x + 3 * y <= 60)); C.assert(ok, 'simplified equivalent'); C.model([60, 25]); });
Q('s205', mk.short({ marks: 2, stem: r`For the region $2x + y \ge 8$, $x + 2y \ge 7$, $x, y \ge 0$ (corners $(0, 8)$, $(3, 2)$, $(7, 0)$), a student lists $Z = 2x + 3y$ at the corners and says "the minimum is $12$". What extra step is needed before this is accepted, and does it succeed?`, model: r`The region is **unbounded**, so the smallest corner value need not be the minimum. Corner values are $24$, $12$, $14$; we must check that the open half-plane $2x + 3y < 12$ has no point in common with the region.

It has none (the line $2x + 3y = 12$ touches the region only at $(3, 2)$), so the minimum is indeed $12$ at $(3, 2)$.`, sol: 'Half-plane test for an unbounded region.', scheme: [['Names the half-plane test 2x + 3y < 12', 1], ['No common point, so min 12 at (3, 2)', 1]], d: 3, c: 'analysis', t: [2], time: 120 }), (C) => { const s = S('C', 2, 3, 'min'); C.assert(!s.bounded && s.exists && s.value === 12 && sameSet(s.at, [[3, 2]]), 'min 12'); C.model([24, 12, 14]); });
Q('s206', mk.short({ marks: 2, stem: r`The objective $Z = px + qy$ ($p, q > 0$) takes its maximum on a bounded region at both corners $(3, 4)$ and $(5, 0)$. Find the relation between $p$ and $q$.`, model: r`Equal values at both corners: $3p + 4q = 5p$.

So $4q = 2p$, that is $p = 2q$.`, sol: 'Equate Z at the two corners.', scheme: [['3p + 4q = 5p', 1], ['p = 2q', 1]], d: 3, c: 'application', t: [2], time: 90 }), (C) => { const s = S('F', 2 * 3, 3, 'max'); C.assert(has(s.at, 3, 4) && has(s.at, 5, 0), 'p = 2q makes both optimal (p = 6, q = 3)'); C.model(['p = 2q']); });
Q('s207', mk.short({ marks: 2, stem: r`A Varanasi weaver's plan must satisfy $x + y \le 7$ and $2x + y \le 10$ with $x, y \ge 0$. Find the plan that maximises $Z = 5x + y$ and the maximum value.`, model: r`Corners: $(0, 0)$, $(5, 0)$, $(3, 4)$, $(0, 7)$.

$Z$: $0$, $25$, $19$, $7$. Maximum $25$ at $x = 5$, $y = 0$.`, sol: 'Corner-point method.', scheme: [['Corners found', 1], ['Max 25 at (5, 0)', 1]], d: 2, c: 'understanding', t: [2], time: 120 }), (C) => { const s = S('B', 5, 1, 'max'); C.assert(sameSet(s.at, [[5, 0]]), 'at (5, 0)'); C.model([s.value, 19, 7]); });
Q('s208', mk.short({ marks: 2, stem: r`Show that $Z = x + y$ has no maximum value on the region $2x + y \ge 8$, $x + 2y \ge 7$, $x \ge 0$, $y \ge 0$.`, model: r`The corners $(0, 8)$, $(3, 2)$, $(7, 0)$ give $Z = 8$, $5$, $7$; the largest is $8$. The region is unbounded, so test the open half-plane $x + y > 8$.

The point $(10, 10)$ is feasible ($30 \ge 8$, $30 \ge 7$) and has $x + y = 20 > 8$. So the half-plane meets the region and $Z$ has **no maximum**.`, sol: 'Unbounded region: the half-plane test fails.', scheme: [['Corner values and largest 8', 1], ['Feasible point with Z > 8, so no maximum', 1]], d: 3, c: 'analysis', t: [2], time: 120 }), (C) => { const s = S('C', 1, 1, 'max'); C.assert(!s.exists && feasible(REG.C, 10, 10), 'no max'); C.model([8, 5, 7, 20]); });
Q('s209', mk.short({ marks: 2, stem: r`A nursery in Pune grows $x$ small pots and $y$ large pots of tulsi. The owner insists that the number of large pots be at least twice the number of small pots, and that no more than $90$ pots be grown in all. Express both conditions as linear constraints.`, model: r`"Large at least twice small": $y \ge 2x$, written as $2x - y \le 0$.

"At most $90$ pots": $x + y \le 90$, together with $x \ge 0$, $y \ge 0$.`, sol: 'Translate each sentence into an inequality.', scheme: [['2x − y ≤ 0', 1], ['x + y ≤ 90', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { C.assert([[10, 20], [10, 19], [30, 60], [31, 60]].map(([x, y]) => feasible([[2, -1, '<=', 0], [1, 1, '<=', 90]], x, y)).join() === 'true,false,true,false', 'translation'); C.model([90]); });

// =============================================================== short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`Solve graphically: maximise $Z = 2x + 3y$ subject to $x + y \le 7$, $2x + y \le 10$, $x \ge 0$, $y \ge 0$.`, model: r`Draw $x + y = 7$ through $(7, 0)$, $(0, 7)$ and $2x + y = 10$ through $(5, 0)$, $(0, 10)$. Both are "$\le$" with the origin satisfying them, so the region is on the origin side: a quadrilateral.

Corners: $O(0, 0)$; $(5, 0)$; the intersection of the lines, $x = 3$, $y = 4$; and $(0, 7)$.

$Z$: $0$, $10$, $18$, $21$. Maximum $21$ at $x = 0$, $y = 7$.`, sol: 'Corner-point method on a bounded region.', scheme: [['Lines and feasible region', 1], ['Corners including (3, 4)', 1], ['Max 21 at (0, 7)', 1]], d: 2, c: 'understanding', t: [2], time: 180 }), (C) => { const s = S('B', 2, 3, 'max'); C.assert(sameSet(s.at, [[0, 7]]), 'at (0, 7)'); C.model([s.value, 18, 10]); });
Q('s302', mk.short({ marks: 3, stem: r`Minimise $Z = 4x + 6y$ subject to $2x + y \ge 8$, $x + 2y \ge 7$, $x \ge 0$, $y \ge 0$.`, model: r`The region lies on the side of each line away from the origin and is unbounded. Corners: $(0, 8)$; the intersection of $2x + y = 8$ and $x + 2y = 7$, which is $(3, 2)$; and $(7, 0)$.

$Z$: $48$, $24$, $28$. Smallest corner value: $24$.

Unbounded, so test $4x + 6y < 24$, i.e. $2x + 3y < 12$: it has no point in common with the region. Minimum $Z = 24$ at $(3, 2)$.`, sol: 'Corner values, then the half-plane test.', scheme: [['Corners (0, 8), (3, 2), (7, 0)', 1], ['Corner values', 1], ['Half-plane check; min 24 at (3, 2)', 1]], d: 3, c: 'application', t: [2], time: 210 }), (C) => { const s = S('C', 4, 6, 'min'); C.assert(s.exists && !s.bounded && sameSet(s.at, [[3, 2]]), 'min at (3, 2)'); C.model([s.value, 48, 28]); });
Q('s303', mk.short({ marks: 3, stem: r`A dairy cooperative near Anand fills $x$ one-litre pouches and $y$ half-litre pouches each hour. It has at most $600$ litres of milk per hour, and its machine needs $3$ seconds per one-litre pouch and $2$ seconds per half-litre pouch. Profit is ₹$3$ per one-litre and ₹$2$ per half-litre pouch. Formulate the problem of maximising hourly profit (do not solve).`, model: r`Decision variables: $x$ one-litre pouches, $y$ half-litre pouches per hour.

Objective: maximise $Z = 3x + 2y$.

Milk: $x + 0.5y \le 600$, i.e. $2x + y \le 1200$. Machine time in one hour ($3600$ s): $3x + 2y \le 3600$. Non-negativity: $x \ge 0$, $y \ge 0$.`, sol: 'Variables, objective, one constraint per resource.', scheme: [['Variables and objective Z = 3x + 2y', 1], ['2x + y ≤ 1200', 1], ['3x + 2y ≤ 3600 and non-negativity', 1]], d: 2, c: 'application', t: [1], time: 180 }), (C) => { C.assert([[600, 0], [0, 1200], [300, 600], [400, 500]].every(([x, y]) => (x + 0.5 * y <= 600) === (2 * x + y <= 1200)), 'milk'); C.model([1200, 3600]); });
Q('s304', mk.short({ marks: 3, stem: r`A Jalandhar sports shop's weekly order must satisfy $x + y \le 10$, $x \le 6$, $y \le 8$, $x, y \ge 0$. Find the order that maximises $Z = 3x + 2y$.`, model: r`The region is a pentagon with corners $(0, 0)$, $(6, 0)$, $(6, 4)$, $(2, 8)$, $(0, 8)$ — for example $(6, 4)$ is where $x = 6$ meets $x + y = 10$.

$Z$: $0$, $18$, $26$, $22$, $16$.

Maximum $26$ at $x = 6$, $y = 4$.`, sol: 'Five corners from three non-trivial constraints.', scheme: [['All five corners', 1], ['Corner values', 1], ['Max 26 at (6, 4)', 1]], d: 2, c: 'understanding', t: [2], time: 180 }), (C) => { const s = S('E', 3, 2, 'max'); C.assert(s.corners.length === 5 && sameSet(s.at, [[6, 4]]), 'max at (6, 4)'); C.model([s.value, 18, 22, 16]); });
Q('s305', mk.short({ marks: 3, stem: r`Show that $Z = 4x + 2y$, subject to $x + 3y \le 15$, $2x + y \le 10$, $x \ge 0$, $y \ge 0$, has infinitely many points of maximum, and describe them.`, model: r`Corners: $(0, 0)$, $(5, 0)$, the intersection of the two lines $(3, 4)$, and $(0, 5)$.

$Z$: $0$, $20$, $20$, $10$. The maximum $20$ occurs at two adjacent corners $(5, 0)$ and $(3, 4)$.

$Z = 4x + 2y = 2(2x + y)$ is parallel to the boundary $2x + y = 10$, so every point of the segment from $(5, 0)$ to $(3, 4)$ gives $Z = 20$: infinitely many optimal points.`, sol: 'Objective parallel to a boundary edge.', scheme: [['Corners', 1], ['Equal maximum 20 at two adjacent corners', 1], ['Whole edge optimal, with reason', 1]], d: 3, c: 'analysis', t: [2], time: 180 }), (C) => { const s = S('F', 4, 2, 'max'); C.assert(s.at.length === 2 && feasible(REG.F, 4, 2) && 4 * 4 + 2 * 2 === 20, 'edge optimal'); C.model([s.value, 10]); });
Q('s306', mk.short({ marks: 3, stem: r`For the feasible region $x + y \ge 2$, $x \le 4$, $y \le 3$, $x \ge 0$, $y \ge 0$, find both the maximum and the minimum of $Z = x + 3y$.`, model: r`Corners: $(2, 0)$, $(4, 0)$, $(4, 3)$, $(0, 3)$, $(0, 2)$ (the origin is excluded by $x + y \ge 2$).

$Z$: $2$, $4$, $13$, $9$, $6$.

Maximum $13$ at $(4, 3)$; minimum $2$ at $(2, 0)$.`, sol: 'Bounded pentagon: compare all corner values.', scheme: [['Five corners', 1], ['Corner values', 1], ['Max 13 at (4, 3), min 2 at (2, 0)', 1]], d: 2, c: 'understanding', t: [2], time: 180 }), (C) => { const a = S('K', 1, 3, 'max'), b = S('K', 1, 3, 'min'); C.assert(sameSet(a.at, [[4, 3]]) && sameSet(b.at, [[2, 0]]), 'optima'); C.model([a.value, b.value, 9, 6]); });
Q('s307', mk.short({ marks: 3, stem: r`Minimise $Z = 3x + 2y$ subject to $3x + y \ge 9$, $x + y \ge 5$, $x + 3y \ge 9$, $x \ge 0$, $y \ge 0$.`, model: r`Corners of the unbounded region: $(0, 9)$; $3x + y = 9$ with $x + y = 5$ gives $(2, 3)$; $x + y = 5$ with $x + 3y = 9$ gives $(3, 2)$; and $(9, 0)$.

$Z$: $18$, $12$, $13$, $27$. Smallest: $12$ at $(2, 3)$.

Half-plane $3x + 2y < 12$: no feasible point lies in it, so the minimum is $12$ at $x = 2$, $y = 3$.`, sol: 'Three non-trivial constraints, unbounded region.', scheme: [['Four corners', 1], ['Corner values', 1], ['Half-plane test; min 12 at (2, 3)', 1]], d: 3, c: 'application', t: [2], time: 210 }), (C) => { const s = S('H', 3, 2, 'min'); C.assert(s.exists && sameSet(s.at, [[2, 3]]), 'min at (2, 3)'); C.model([s.value, 18, 13, 27]); });
Q('s308', mk.short({ marks: 3, stem: r`Explain why the problem "maximise $Z = x + y$ subject to $x + y \le 3$, $2x + 3y \ge 12$, $x \ge 0$, $y \ge 0$" has no solution.`, model: r`For any point with $x, y \ge 0$ and $x + y \le 3$: $2x + 3y = 2(x + y) + y \le 2(3) + 3 = 9$.

So $2x + 3y \le 9 < 12$, and the constraint $2x + 3y \ge 12$ cannot hold together with the others.

The feasible region is **empty**: there is no feasible point, hence no optimal solution.`, sol: 'Show the constraints are inconsistent.', scheme: [['Bound 2x + 3y ≤ 9 on x + y ≤ 3', 1], ['Contradiction with ≥ 12', 1], ['Empty region, no solution', 1]], d: 4, c: 'analysis', t: [2], time: 180 }), (C) => { C.assert(S('G', 1, 1, 'max').empty && S([[1, 1, '<=', 3]], 2, 3, 'max').value === 9, 'empty, bound 9'); C.model([9, 12]); });

// =============================================================== long answer, 5 marks
Q('l01', mk.long({ stem: r`Solve the following linear programming problem graphically: maximise $Z = 4x + 3y$ subject to $3x + 2y \le 18$, $x + 2y \le 10$, $x \ge 0$, $y \ge 0$.`, model: r`**Lines.** $3x + 2y = 18$ passes through $(6, 0)$ and $(0, 9)$; $x + 2y = 10$ through $(10, 0)$ and $(0, 5)$. The origin satisfies both "$\le$" constraints, so the region is on the origin side of each line, in the first quadrant.

**Corners.** $O(0, 0)$, $A(6, 0)$, $D(0, 5)$, and $B$ where the lines meet: subtracting, $2x = 8$, $x = 4$, $y = 3$, so $B(4, 3)$.

**Values.** $Z(O) = 0$, $Z(A) = 24$, $Z(B) = 16 + 9 = 25$, $Z(D) = 15$.

**Conclusion.** The region is bounded, so the maximum is $25$ at $x = 4$, $y = 3$.`, sol: 'Corner-point method, bounded region.', scheme: [['Both lines drawn with intercepts', 1], ['Feasible region identified', 1], ['Corner B(4, 3) found', 1], ['Corner values', 1], ['Max 25 at (4, 3)', 1]], d: 3, c: 'application', t: [2], time: 420 }), (C) => { const s = S('A', 4, 3, 'max'); C.assert(sameSet(s.at, [[4, 3]]) && s.bounded, 'max (4, 3)'); C.model([s.value, 24, 15]); });
Q('l02', mk.long({ stem: r`Minimise $Z = 5x + 2y$ subject to $3x + y \ge 9$, $x + y \ge 5$, $x + 3y \ge 9$, $x \ge 0$, $y \ge 0$. Show the half-plane check clearly.`, model: r`**Lines.** $3x + y = 9$: $(3, 0)$, $(0, 9)$. $x + y = 5$: $(5, 0)$, $(0, 5)$. $x + 3y = 9$: $(9, 0)$, $(0, 3)$. The origin fails every "$\ge$" constraint, so the region lies away from the origin; it is unbounded.

**Corners.** $(0, 9)$; $3x + y = 9$ and $x + y = 5$ give $x = 2$, $y = 3$; $x + y = 5$ and $x + 3y = 9$ give $x = 3$, $y = 2$; and $(9, 0)$.

**Values.** $Z(0, 9) = 18$, $Z(2, 3) = 16$, $Z(3, 2) = 19$, $Z(9, 0) = 45$. Smallest: $16$.

**Half-plane check.** Draw $5x + 2y = 16$; the open half-plane $5x + 2y < 16$ has no point in common with the region (the line touches it only at $(2, 3)$).

**Conclusion.** Minimum $Z = 16$ at $x = 2$, $y = 3$.`, sol: 'Unbounded region: smallest corner value confirmed by the half-plane test.', scheme: [['Three lines and unbounded region', 1], ['Corners (2, 3) and (3, 2) found', 1], ['Corner values', 1], ['Half-plane 5x + 2y < 16 checked', 1], ['Min 16 at (2, 3)', 1]], d: 4, c: 'application', t: [2], time: 480 }), (C) => { const s = S('H', 5, 2, 'min'); C.assert(s.exists && !s.bounded && sameSet(s.at, [[2, 3]]), 'min (2, 3)'); C.model([s.value, 18, 19, 45]); });
Q('l03', mk.long({ stem: r`A tailoring unit in Tiruppur makes shirts and kurtas. A shirt needs $1$ hour of cutting and $3$ hours of stitching; a kurta needs $2$ hours of cutting and $2$ hours of stitching. Each day at most $16$ cutting hours and $24$ stitching hours are available. The profit is ₹$50$ on a shirt and ₹$70$ on a kurta. Formulate a linear programming problem and solve it graphically to find the most profitable daily plan.`, model: r`**Formulation.** Let $x$ shirts and $y$ kurtas be made. Maximise $Z = 50x + 70y$ subject to cutting $x + 2y \le 16$, stitching $3x + 2y \le 24$, $x \ge 0$, $y \ge 0$.

**Lines.** $x + 2y = 16$: $(16, 0)$, $(0, 8)$. $3x + 2y = 24$: $(8, 0)$, $(0, 12)$. Region on the origin side of both.

**Corners.** $(0, 0)$, $(8, 0)$, $(0, 8)$ and the intersection: subtracting, $2x = 8$, $x = 4$, $y = 6$.

**Values.** $Z(8, 0) = 400$, $Z(4, 6) = 200 + 420 = 620$, $Z(0, 8) = 560$, $Z(0, 0) = 0$.

**Answer.** Make $4$ shirts and $6$ kurtas a day for the maximum profit ₹$620$.`, sol: 'Formulate, then corner-point method.', scheme: [['Variables and objective', 1], ['Both constraints', 1], ['Corners including (4, 6)', 1], ['Corner values', 1], ['Plan 4 shirts, 6 kurtas, ₹620', 1]], d: 3, c: 'application', t: [1, 2], time: 540 }), (C) => { const s = S([[1, 2, '<=', 16], [3, 2, '<=', 24]], 50, 70, 'max'); C.assert(sameSet(s.at, [[4, 6]]), 'plan (4, 6)'); C.model([s.value, 400, 560]); });
Q('l04', mk.long({ stem: r`Find the maximum and minimum values of $Z = 3x + 4y$ subject to $x + 2y \ge 4$, $x + y \le 6$, $x \le 5$, $x \ge 0$, $y \ge 0$, and state where each occurs.`, model: r`**Lines.** $x + 2y = 4$: $(4, 0)$, $(0, 2)$, region away from the origin. $x + y = 6$: $(6, 0)$, $(0, 6)$, region on the origin side. $x = 5$: region to its left.

**Corners.** $(4, 0)$, $(5, 0)$, $(5, 1)$ (where $x = 5$ meets $x + y = 6$), $(0, 6)$, $(0, 2)$. The region is bounded.

**Values.** $Z(4, 0) = 12$, $Z(5, 0) = 15$, $Z(5, 1) = 19$, $Z(0, 6) = 24$, $Z(0, 2) = 8$.

**Conclusion.** Maximum $24$ at $(0, 6)$; minimum $8$ at $(0, 2)$.`, sol: 'Bounded region with a mixture of constraint directions.', scheme: [['Three lines and region', 1], ['Five corners', 1], ['Corner values', 1], ['Max 24 at (0, 6)', 1], ['Min 8 at (0, 2)', 1]], d: 3, c: 'application', t: [2], time: 480 }), (C) => { const a = S('D5', 3, 4, 'max'), b = S('D5', 3, 4, 'min'); C.assert(a.corners.length === 5 && sameSet(a.at, [[0, 6]]) && sameSet(b.at, [[0, 2]]), 'optima'); C.model([a.value, b.value, 12, 15, 19]); });
Q('l05', mk.long({ stem: r`For the region $2x + y \ge 8$, $x + 2y \ge 7$, $x \ge 0$, $y \ge 0$: (a) show that $Z = x + 2y$ has a minimum and find all the points where it occurs; (b) show that the same $Z$ has no maximum on this region.`, model: r`**Corners.** $2x + y = 8$ meets $x + 2y = 7$ at $(3, 2)$; the other corners are $(0, 8)$ and $(7, 0)$. The region is unbounded.

**(a)** $Z(0, 8) = 16$, $Z(3, 2) = 7$, $Z(7, 0) = 7$. Smallest: $7$. The half-plane $x + 2y < 7$ contradicts the constraint $x + 2y \ge 7$, so it has no feasible point: the minimum is $7$. It is attained at $(3, 2)$, at $(7, 0)$ and at **every point of the segment joining them**, because $Z$ is constant along the boundary line $x + 2y = 7$ — infinitely many points.

**(b)** The largest corner value is $16$. But $(20, 20)$ is feasible and $Z(20, 20) = 60 > 16$; the half-plane $x + 2y > 16$ meets the region, so $Z$ has no maximum.`, sol: 'Minimum along an edge; no maximum on an unbounded region.', scheme: [['Corners and unboundedness', 1], ['Corner values', 1], ['Half-plane test gives min 7', 1], ['Whole edge from (3, 2) to (7, 0) optimal', 1], ['No maximum, with a feasible point beyond 16', 1]], d: 5, c: 'analysis', t: [2], time: 480 }), (C) => { const a = S('C', 1, 2, 'min'), b = S('C', 1, 2, 'max'); C.assert(a.exists && a.at.length === 2 && !b.exists && feasible(REG.C, 20, 20), 'min on edge, no max'); C.model([a.value, 16, 60]); });
Q('l06', mk.long({ stem: r`A school in Lucknow is planning an excursion for at least $160$ students. It can hire vans that seat $10$ students for ₹$1500$ each and buses that seat $40$ students for ₹$4000$ each. Only $10$ drivers are available, so at most $10$ vehicles can be hired, and the depot has only $3$ buses. How many of each should be hired to keep the cost as low as possible?`, model: r`**Formulation.** $x$ vans, $y$ buses. Minimise $C = 1500x + 4000y$ subject to seats $10x + 40y \ge 160$, i.e. $x + 4y \ge 16$; drivers $x + y \le 10$; buses $y \le 3$; $x, y \ge 0$.

**Corners.** $y = 3$ with $x + 4y = 16$: $(4, 3)$. $y = 3$ with $x + y = 10$: $(7, 3)$. $x + y = 10$ with $x + 4y = 16$: $3y = 6$, so $(8, 2)$. (On the axes, $x + 4y \ge 16$ would need $x \ge 16$ or $y \ge 4$, both impossible here.) The region is the bounded triangle with these corners.

**Values.** $C(4, 3) = 6000 + 12000 = 18000$, $C(7, 3) = 22500$, $C(8, 2) = 20000$.

**Answer.** Hire $4$ vans and $3$ buses; minimum cost ₹$18000$.`, sol: 'Three non-trivial constraints, bounded triangular region.', scheme: [['Formulation with x + 4y ≥ 16', 1], ['x + y ≤ 10 and y ≤ 3', 1], ['Three corners', 1], ['Costs at corners', 1], ['4 vans, 3 buses, ₹18000', 1]], d: 4, c: 'application', t: [1, 2], time: 540 }), (C) => { const s = S([[1, 4, '>=', 16], [1, 1, '<=', 10], [0, 1, '<=', 3]], 1500, 4000, 'min'); C.assert(sameSet(s.corners, [[4, 3], [7, 3], [8, 2]]) && sameSet(s.at, [[4, 3]]), 'triangle, min (4, 3)'); C.model([18000, 22500, 20000]); });

// =============================================================== case-based (1 + 1 + 2, either/or part (c))
caseQ('c01', {
  passage: r`A spice exporter in Kochi packs small and large gift boxes of pepper and cardamom. A small box needs $1$ hour of hand-sorting and $2$ units of packing material; a large box needs $3$ hours of sorting and $1$ unit of material. Each day there are at most $45$ sorting hours and $40$ units of material. The profit is ₹$40$ on a small box and ₹$70$ on a large box. Let $x$ small and $y$ large boxes be packed.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $x + 3y \le 45$. (b) $y = 10$ (corner $(15, 10)$). (c) (i) $15$ small and $10$ large boxes, profit ₹$1300$. Or (ii) The best plan becomes $0$ small and $15$ large boxes, profit ₹$1950$.`,
  sol: r`Corners $(0, 0)$, $(20, 0)$, $(15, 10)$, $(0, 15)$. With $Z = 40x + 70y$: $0$, $800$, $1300$, $1050$. With $Z = 40x + 130y$: $0$, $800$, $1900$, $1950$.`,
  children: [
    child('a', mk.mcq({ stem: 'The constraint coming from the sorting hours is', opts: [r`$x + 3y \le 45$`, r`$3x + y \le 45$`, r`$2x + y \le 40$`, r`$x + 3y \ge 45$`], key: 'a', sol: r`Sorting hours: $1 \cdot x + 3 \cdot y$ cannot exceed $45$. Option (c) is the material constraint.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: r`The lines $x + 3y = 45$ and $2x + y = 40$ meet at a corner of the feasible region. Find the value of $y$ there.`, value: 10, sol: r`From $2x + y = 40$, $y = 40 - 2x$; then $x + 120 - 6x = 45$, so $x = 15$ and $y = 10$.`, scheme: [['10', 1]], d: 2, c: 'understanding', t: [2], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the number of boxes of each kind that gives the maximum daily profit, and the profit.', model: r`Corners: $(0, 0)$, $(20, 0)$, $(15, 10)$, $(0, 15)$. $Z = 40x + 70y$: $0$, $800$, $1300$, $1050$. Maximum ₹$1300$ with $15$ small and $10$ large boxes.`, sol: 'Evaluate profit at the corners.', scheme: [['Corner values', 1], ['15 small, 10 large, ₹1300', 1]], d: 3, c: 'application', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: '**(ii)** During the festival season the profit on a large box rises to ₹130 while a small box still earns ₹40. Find the new best plan and profit.', model: r`Same corners. $Z = 40x + 130y$: $(20, 0) \to 800$, $(15, 10) \to 1900$, $(0, 15) \to 1950$. The best plan becomes $0$ small and $15$ large boxes, profit ₹$1950$.`, sol: 'Only the objective changes; recompute the corner values.', scheme: [['New corner values', 1], ['0 small, 15 large, ₹1950', 1]], d: 3, c: 'analysis', t: [2], time: 180 }),
    ]),
  ],
}, (C) => { const reg = [[1, 3, '<=', 45], [2, 1, '<=', 40]]; const a = S(reg, 40, 70, 'max'), b = S(reg, 40, 130, 'max'); C.child('a').key('a'); C.child('b').val(10); C.assert(has(a.corners, 15, 10), 'corner (15, 10)'); C.child('c').model([a.value, 15, 10]); C.assert(sameSet(a.at, [[15, 10]]) && sameSet(b.at, [[0, 15]]), 'plans'); C.child('cii').model([b.value, 1900, 15]); });

caseQ('c02', {
  passage: r`A farmer near Nashik needs at least $15$ kg of nitrogen and $10$ kg of phosphate for a field. Fertiliser bag F1 supplies $3$ kg of nitrogen and $1$ kg of phosphate and costs ₹$300$; bag F2 supplies $1$ kg of nitrogen and $2$ kg of phosphate and costs ₹$250$. Let $x$ bags of F1 and $y$ bags of F2 be bought. The constraints are $3x + y \ge 15$, $x + 2y \ge 10$, $x, y \ge 0$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): unbounded. (b) ₹$1950$ at $(4, 3)$ — the smallest corner cost. (c) (i) Corners $(0, 15)$, $(4, 3)$, $(10, 0)$ with costs ₹$3750$, ₹$1950$, ₹$3000$; half-plane test passes, so buy $4$ F1 and $3$ F2 bags for ₹$1950$. Or (ii) No: the region is unbounded and the cost grows without limit, e.g. $(50, 50)$ is feasible and costs ₹$27500$.`,
  sol: r`Corners: $(0, 15)$, $(4, 3)$, $(10, 0)$. Costs $300x + 250y$: $3750$, $1950$, $3000$. The open half-plane $300x + 250y < 1950$ has no feasible point.`,
  children: [
    child('a', mk.mcq({ stem: 'The feasible region of this problem is', opts: ['unbounded', 'bounded', 'empty', 'a single point'], key: 'a', sol: r`Both constraints are "$\ge$" type and large purchases such as $(50, 50)$ satisfy them: the region is unbounded.`, d: 1, c: 'understanding', t: [2], time: 45 })),
    child('b', mk.num({ stem: 'Find the cost (in ₹) at the corner where the two boundary lines meet.', value: 1950, unit: '₹', sol: r`$3x + y = 15$ and $x + 2y = 10$ meet at $(4, 3)$; cost $1200 + 750 = 1950$.`, scheme: [['1950', 1]], d: 2, c: 'understanding', t: [2], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the cheapest purchase that meets both needs, justifying that it is a true minimum.', model: r`Corners $(0, 15)$, $(4, 3)$, $(10, 0)$: costs ₹$3750$, ₹$1950$, ₹$3000$. The region is unbounded, but the half-plane $300x + 250y < 1950$ has no point in common with it. So buy $4$ bags of F1 and $3$ bags of F2; minimum cost ₹$1950$.`, sol: 'Corner costs, then the half-plane test.', scheme: [['Corner costs', 1], ['Half-plane test, 4 F1 + 3 F2 at ₹1950', 1]], d: 3, c: 'application', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: '**(ii)** The farmer asks: "Is there a most expensive way to meet the needs?" Answer with a reason.', model: r`No. The region is unbounded: $(50, 50)$ is feasible ($200 \ge 15$, $150 \ge 10$) and costs ₹$27500$, more than every corner cost, and larger purchases cost even more. So the cost has no maximum.`, sol: 'Unbounded region and a feasible point beyond every corner cost.', scheme: [['Feasible point costing more than any corner', 1], ['No maximum', 1]], d: 3, c: 'analysis', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const reg = [[3, 1, '>=', 15], [1, 2, '>=', 10]]; const s = S(reg, 300, 250, 'min'), m = S(reg, 300, 250, 'max'); C.assert(!s.bounded && s.exists && sameSet(s.at, [[4, 3]]) && !m.exists && feasible(reg, 50, 50), 'min (4, 3), no max'); C.child('a').key('a'); C.child('b').val(s.value); C.child('c').model([s.value, 3750, 3000]); C.child('cii').model([300 * 50 + 250 * 50]); });

caseQ('c03', {
  passage: r`A farmer in Haryana has $12$ acres for wheat and mustard this rabi season. Wheat needs $4$ units of canal water per acre and mustard $2$ units, and only $36$ units are allotted. The expected profit is ₹$5000$ per acre of wheat and ₹$4000$ per acre of mustard. Let $x$ acres of wheat and $y$ acres of mustard be sown.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $2x + y \le 18$. (b) $4$ corners. (c) (i) $6$ acres of each crop, profit ₹$54000$. Or (ii) At $(9, 0)$, $3$ acres stay unused and the profit is ₹$45000$, which is ₹$9000$ less than the best plan.`,
  sol: r`Constraints $x + y \le 12$, $2x + y \le 18$, $x, y \ge 0$. Corners $(0, 0)$, $(9, 0)$, $(6, 6)$, $(0, 12)$; profits $0$, $45000$, $54000$, $48000$.`,
  children: [
    child('a', mk.mcq({ stem: 'The water constraint, in simplest form, is', opts: [r`$2x + y \le 18$`, r`$x + 2y \le 18$`, r`$4x + 2y \ge 36$`, r`$x + y \le 12$`], key: 'a', sol: r`Water: $4x + 2y \le 36$, i.e. $2x + y \le 18$. Option (d) is the land constraint.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: 'How many corner points does the feasible region have?', value: 4, sol: r`$(0, 0)$, $(9, 0)$, $(6, 6)$ and $(0, 12)$: $4$ corners.`, scheme: [['4', 1]], d: 2, c: 'understanding', t: [2], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** How many acres of each crop should be sown for the greatest profit? Find the profit.', model: r`Corner profits: $(9, 0) \to 45000$, $(6, 6) \to 30000 + 24000 = 54000$, $(0, 12) \to 48000$, $(0, 0) \to 0$. Sow $6$ acres of wheat and $6$ of mustard; profit ₹$54000$.`, sol: 'Corner-point method.', scheme: [['Corner profits', 1], ['6 acres each, ₹54000', 1]], d: 3, c: 'application', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: '**(ii)** A neighbour advises sowing only wheat on as much land as the water allows. Compare this plan with the best plan.', model: r`Only wheat: $2x \le 18$ gives $x = 9$ acres (so $3$ acres stay unused), profit $9 \times 5000 = 45000$. The best plan $(6, 6)$ gives ₹$54000$, so the advice loses ₹$9000$.`, sol: 'Evaluate the advised corner and compare.', scheme: [['(9, 0) and ₹45000', 1], ['₹9000 less than the best', 1]], d: 3, c: 'evaluation', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const reg = [[1, 1, '<=', 12], [2, 1, '<=', 18]]; const s = S(reg, 5000, 4000, 'max'); C.assert(sameSet(s.at, [[6, 6]]) && [[9, 0], [6, 6], [0, 12], [0, 0]].every(([x, y]) => has(s.corners, x, y)), 'corners'); C.child('a').key('a'); C.child('b').val(s.corners.length); C.child('c').model([s.value, 45000, 48000]); C.child('cii').model([45000, s.value - 45000]); });

caseQ('c04', {
  passage: r`A handicraft unit in Jaipur makes brass lamps ($x$) and clay vases ($y$) each week. A lamp needs $2$ hours on the polishing machine and $1$ hour of a craftsman's time; a vase needs $1$ hour on the machine and $2$ hours of a craftsman's time. The machine is free for $20$ hours and the craftsmen for $22$ hours a week, and the kiln can fire at most $10$ vases. Profit: ₹$300$ per lamp and ₹$250$ per vase.`,
  d: 4, c: 'application',
  model: r`(a) Option (a): five corners. (b) ₹$3800$ at $(6, 8)$. (c) (i) $6$ lamps and $8$ vases, profit ₹$3800$; the other corner profits are ₹$0$, ₹$3000$, ₹$3100$, ₹$2500$. Or (ii) No: $(5, 10)$ needs $25$ craftsman hours but only $22$ are available, so it is infeasible.`,
  sol: r`Constraints $2x + y \le 20$, $x + 2y \le 22$, $y \le 10$, $x, y \ge 0$. Corners $(0, 0)$, $(10, 0)$, $(6, 8)$, $(2, 10)$, $(0, 10)$. Profits $0$, $3000$, $3800$, $3100$, $2500$.`,
  children: [
    child('a', mk.mcq({ stem: 'How many corner points does the feasible region have?', opts: ['$5$', '$4$', '$3$', '$6$'], key: 'a', sol: r`$(0, 0)$, $(10, 0)$, $(6, 8)$, $(2, 10)$, $(0, 10)$: five corners.`, d: 2, c: 'understanding', t: [2], time: 90 })),
    child('b', mk.num({ stem: r`Find the profit (in ₹) at the corner where $2x + y = 20$ meets $x + 2y = 22$.`, value: 3800, unit: '₹', sol: r`The lines meet at $(6, 8)$; profit $1800 + 2000 = 3800$.`, scheme: [['3800', 1]], d: 2, c: 'understanding', t: [2], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the weekly plan that gives the maximum profit.', model: r`Corner profits: $(0, 0) \to 0$, $(10, 0) \to 3000$, $(6, 8) \to 3800$, $(2, 10) \to 3100$, $(0, 10) \to 2500$. Make $6$ lamps and $8$ vases; maximum profit ₹$3800$.`, sol: 'Five corners, compare the profits.', scheme: [['Corner profits', 1], ['6 lamps, 8 vases, ₹3800', 1]], d: 3, c: 'application', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: '**(ii)** The manager suggests making 5 lamps and 10 vases. Is this plan possible? Justify.', model: r`Check each constraint at $(5, 10)$: machine $10 + 10 = 20 \le 20$; kiln $10 \le 10$; craftsmen $5 + 20 = 25 > 22$. The craftsman constraint fails, so the plan is **not feasible**.`, sol: 'Test the point in every constraint.', scheme: [['All constraints tested', 1], ['Craftsman hours 25 > 22: infeasible', 1]], d: 3, c: 'evaluation', t: [2], time: 120 }),
    ]),
  ],
}, (C) => { const reg = [[2, 1, '<=', 20], [1, 2, '<=', 22], [0, 1, '<=', 10]]; const s = S(reg, 300, 250, 'max'); C.child('a').which([5, 4, 3, 6], s.corners.length); C.child('b').val(300 * 6 + 250 * 8); C.assert(sameSet(s.at, [[6, 8]]) && !feasible(reg, 5, 10), 'optimum and infeasible plan'); C.child('c').model([s.value, 3000, 3100, 2500]); C.child('cii').model([25, 22]); });

caseQ('c05', {
  passage: r`A tiffin service in Delhi packs vegetarian ($x$) and non-vegetarian ($y$) lunch boxes. The packing line can handle at most $60$ boxes a day, and kitchen time limits them by $x + 2y \le 90$. Each box of either kind earns a profit of ₹$30$.`,
  d: 3, c: 'analysis',
  model: r`(a) Option (a): $Z = 30x + 30y$. (b) $30$ (the corner $(30, 30)$). (c) (i) Maximum ₹$1800$ at both $(60, 0)$ and $(30, 30)$, so every plan on the segment joining them (for example $40$ veg and $20$ non-veg) is optimal. Or (ii) With ₹$40$ on a non-veg box, $Z = 30x + 40y$: $(60, 0) \to 1800$, $(30, 30) \to 2100$, $(0, 45) \to 1800$; the unique best plan is $30$ of each, profit ₹$2100$.`,
  sol: r`Corners $(0, 0)$, $(60, 0)$, $(30, 30)$, $(0, 45)$. $Z = 30x + 30y$: $0$, $1800$, $1800$, $1350$.`,
  children: [
    child('a', mk.mcq({ stem: 'The objective function is', opts: [r`$Z = 30x + 30y$`, r`$Z = x + y$`, r`$Z = 30x + 60y$`, r`$Z = 60x + 90y$`], key: 'a', sol: r`Each box earns ₹$30$, so profit is $30x + 30y$. Option (b) counts boxes, not rupees.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: r`Find the $x$-coordinate of the corner where $x + y = 60$ meets $x + 2y = 90$.`, value: 30, sol: r`Subtract: $y = 30$, then $x = 30$.`, scheme: [['30', 1]], d: 2, c: 'understanding', t: [2], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the maximum profit and describe all the plans that give it.', model: r`Corner profits: $(0, 0) \to 0$, $(60, 0) \to 1800$, $(30, 30) \to 1800$, $(0, 45) \to 1350$. Maximum ₹$1800$ at two adjacent corners, so every point of the segment from $(60, 0)$ to $(30, 30)$ is optimal — for example $40$ veg and $20$ non-veg boxes.`, sol: 'Equal maximum at two adjacent corners.', scheme: [['Corner profits', 1], ['₹1800 on the whole edge', 1]], d: 3, c: 'analysis', t: [2], time: 180 }), [
      mk.short({ marks: 2, stem: '**(ii)** If the profit on a non-vegetarian box rises to ₹40 (vegetarian stays ₹30), find the best plan now.', model: r`$Z = 30x + 40y$: $(60, 0) \to 1800$, $(30, 30) \to 2100$, $(0, 45) \to 1800$, $(0, 0) \to 0$. The unique best plan is $30$ of each kind, profit ₹$2100$.`, sol: 'Recompute the corner values with the new objective.', scheme: [['New corner values', 1], ['30 of each, ₹2100', 1]], d: 3, c: 'application', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const reg = [[1, 1, '<=', 60], [1, 2, '<=', 90]]; const s = S(reg, 30, 30, 'max'), t = S(reg, 30, 40, 'max'); C.child('a').key('a'); C.child('b').val(30); C.assert(s.at.length === 2 && feasible(reg, 40, 20) && 30 * 60 === 1800 && sameSet(t.at, [[30, 30]]), 'edge optimal; unique after change'); C.child('c').model([s.value, 1350, 40, 20]); C.child('cii').model([t.value, 1800]); });

// =============================================================== extra items (competency and coverage)
Q('s210', mk.short({ marks: 2, stem: r`Explain, with the help of the region $x + y \ge 6$, $x + 3y \ge 9$, $x, y \ge 0$, why the smallest corner value of $Z = 2x + 3y$ may be trusted as the minimum here, even though the region is unbounded.`, model: r`Corners $(0, 6)$, $(4.5, 1.5)$, $(9, 0)$ give $Z = 18$, $13.5$, $18$. Smallest: $13.5$.

The open half-plane $2x + 3y < 13.5$ has no point in common with the region, so $13.5$ is the minimum, at $(4.5, 1.5)$.`, sol: 'Half-plane test on an unbounded region.', scheme: [['Corner values', 1], ['Half-plane test passes: min 13.5', 1]], d: 3, c: 'analysis', t: [2], time: 120 }), (C) => { const s = S('R2', 2, 3, 'min'); C.assert(s.exists && !s.bounded, 'min attained'); C.model([s.value, 18, 4.5, 1.5]); });
Q('m19', mk.mcq({ stem: r`For the vehicles a school can hire, the constraints are $x + 4y \ge 16$, $x + y \le 10$, $y \le 3$, $x, y \ge 0$. Which point is **not** feasible?`, opts: ['$(2, 3)$', '$(4, 3)$', '$(8, 2)$', '$(6, 3)$'], key: 'a', sol: r`$(2, 3)$ gives $2 + 12 = 14 < 16$, failing the seat constraint. The others satisfy all three constraints.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { const reg = [[1, 4, '>=', 16], [1, 1, '<=', 10], [0, 1, '<=', 3]]; C.which([[2, 3], [4, 3], [8, 2], [6, 3]].map(([x, y]) => !feasible(reg, x, y)), true); });
